    fun getCourseListForTrack(track: String): List<CourseInfo> {
        return FULL_CURRICULUM.filter { !it.isTrackSpecific || it.requiredTrack == track }
    }

    fun getAllSearchedCourses(track: String): List<CourseInfo> {
        val list = getCourseListForTrack(track).toMutableList()
        // Add required GEs with their actual codes
        list.addAll(REQUIRED_GES)
        // Add elective GEs with their actual codes
        list.addAll(ELECTIVE_GES)
        // Add elective CS subjects
        list.addAll(SPECIAL_ELECTIVES)
        return list.filter { 
            val isGeSlot = it.code.startsWith("GE ") && it.code.substringAfter("GE ").toIntOrNull() != null
            val isPeSlot = it.code.startsWith("PE ") && it.code.substringAfter("PE ").toIntOrNull() != null
            !isGeSlot && !isPeSlot
        }.distinctBy { it.code }
    }

